import {
  invalidCodexConfigKeyPath,
  type Effort,
  type HarnessOptions,
} from '@graphgoblin/contracts';
import type { CodexOptions, ModelReasoningEffort, ThreadOptions } from '@openai/codex-sdk';
import { codexEffortName } from './effort-names.js';
import { isolationDefaults, layerConfig, overrideRefusal, table } from './isolation.js';

/**
 * Building the SDK's client and thread options. The thread settings listed below override their
 * machine defaults. The Windows sandbox backend (`windows.sandbox`) remains inherited unless
 * explicitly configured through an override; it is distinct from the authored `--sandbox`
 * permission level. Configured plugins are inherited while other extensions have isolation
 * defaults (ADR-0067).
 *
 * Verified against `@openai/codex-sdk` 0.160.0 (`dist/index.js`, `CodexExec.run`): the per-thread
 * options are turned into these CLI arguments, which come after any `config` overrides and so win
 * over both them and `config.toml`:
 *
 * | ThreadOptions          | CLI argument                                       |
 * | ---------------------- | -------------------------------------------------- |
 * | `model`                | `--model <id>`                                     |
 * | `modelReasoningEffort` | `--config model_reasoning_effort="<level>"`        |
 * | `sandboxMode`          | `--sandbox read-only|workspace-write|danger-full-access` |
 * | `approvalPolicy`       | `--config approval_policy="never|on-request|on-failure|untrusted"` |
 * | `networkAccessEnabled` | `--config sandbox_workspace_write.network_access=<bool>` |
 * | `webSearchMode`        | `--config web_search="disabled|cached|live"`       |
 * | `workingDirectory`     | `--cd <dir>`                                       |
 * | `skipGitRepoCheck`     | `--skip-git-repo-check`                            |
 *
 * The run records the canonical effort; the CLI receives the provider's name for it, which differs
 * only for `none` in a family that calls that level `minimal` (`effort-names.ts`). CLI 0.160.0
 * passes `model_reasoning_effort` through to the request as `reasoning.effort` without checking
 * it; the model catalog limits each model to the efforts it offers
 * (docs/06-harness-integration.md).
 */

export interface ResolvedSettings {
  model: string;
  effort: Effort;
  options: HarnessOptions;
  workingDirectory?: string;
}

export function threadOptions(settings: ResolvedSettings): ThreadOptions {
  const { options } = settings;
  return {
    model: settings.model,
    // SDK 0.160.0 types this field without `none`; it writes the value into the CLI argument as
    // is, and the CLI forwards it unchanged (verified live for `gpt-6-luna`, #205).
    modelReasoningEffort: codexEffortName(settings.model, settings.effort) as ModelReasoningEffort,
    sandboxMode: options.sandbox,
    approvalPolicy: options.approval,
    networkAccessEnabled: options.networkAccess ?? false,
    webSearchMode: options.webSearch ? 'live' : 'disabled',
    skipGitRepoCheck: true,
    ...(settings.workingDirectory ? { workingDirectory: settings.workingDirectory } : {}),
  };
}

type ConfigValue = NonNullable<CodexOptions['config']>[string];

/**
 * Keep only values the SDK can serialise to TOML (strings, finite numbers, booleans, arrays and
 * objects of those). `null`, `undefined`, and anything else are dropped rather than letting the SDK
 * throw at spawn time.
 */
export function sanitizeConfig(value: unknown): ConfigValue | undefined {
  if (typeof value === 'string' || typeof value === 'boolean') return value;
  if (typeof value === 'number') return Number.isFinite(value) ? value : undefined;
  if (Array.isArray(value)) {
    return value.map(sanitizeConfig).filter((v): v is ConfigValue => v !== undefined);
  }
  if (value && typeof value === 'object') {
    // Authored keys such as `__proto__` stay own keys (QA423-01).
    const out = table();
    for (const [key, child] of Object.entries(value)) {
      const clean = sanitizeConfig(child);
      if (key && clean !== undefined) out[key] = clean;
    }
    return out;
  }
  return undefined;
}

/**
 * Client options: the SDK's `config` (dotted `--config` keys) is the isolation defaults of
 * ADR-0063/ADR-0067 with `harnessOptions.configOverrides` layered over them, so a node can opt
 * out of inherited plugins or turn another extension back on. The thread options are emitted
 * after them, so overrides cannot weaken the sandbox, approval, model, or effort a node declared.
 */
export function clientOptions(
  options: HarnessOptions,
  codexBinary: string | undefined,
  env: Record<string, string> | undefined,
): CodexOptions {
  // A key the loop cannot pass as plain `--config` segments refuses the turn (review round 1).
  const unplain = invalidCodexConfigKeyPath(options.configOverrides);
  if (unplain !== undefined) throw overrideRefusal(unplain.join('.'));
  const overrides = sanitizeConfig(options.configOverrides ?? {}) as NonNullable<
    CodexOptions['config']
  >;
  return {
    ...(codexBinary ? { codexPathOverride: codexBinary } : {}),
    ...(env ? { env } : {}),
    config: layerConfig(isolationDefaults(), overrides),
  };
}

