1	import type { CodexOptions } from '@openai/codex-sdk';
2	import { plainCodexConfigSegment } from '@graphgoblin/contracts';
3	import type { CliCommand, CliRunner } from './cli.js';
4	
5	/**
6	 * Codex turns inherit configured plugins (ADR-0067), with other extensions isolated (ADR-0063).
7	 *
8	 * The CLI loads `~/.codex/config.toml` (and a trusted project's `.codex/config.toml`) for every
9	 * turn. The CLI resolves installed and remote plugins, including their enabled/disabled state
10	 * and their own MCP servers. These defaults still switch off standalone MCP servers, ChatGPT
11	 * apps, memories, goals, sub-agents, lifecycle hooks and the `notify` program.
12	 *
13	 * - `features.<name>=false` switches a feature off; `features.plugins=false` removes every local
14	 *   and remote plugin and the MCP servers they bring.
15	 * - `--config` overrides merge into the loaded tables, so `mcp_servers={}` clears nothing and a
16	 *   non-table value fails the configuration. Each configured server is switched off by name with
17	 *   `mcp_servers.<name>.enabled=false`; naming a server that is not configured also fails the
18	 *   configuration, so the names come from the CLI itself (`codex mcp list --json`).
19	 * - Arrays replace, so `notify=[]` removes the turn-completion program.
20	 * - Among repeated `--config` keys the last one wins.
21	 *
22	 * Order of the `--config` arguments: server switches, these defaults, then the node's own
23	 * `configOverrides` (so a node turns one server back on with `mcp_servers.<name>.enabled=true`,
24	 * or opts out of plugins with `features.plugins=false`), then the SDK's thread options, which no
25	 * override can weaken.
26	 *
27	 * Every key segment that reaches `--config`, a listed server name or a node override key, must be
28	 * one plain TOML key (letters, digits, `_`, `-`) and not `__proto__`, `constructor` or
29	 * `prototype` (QA423-01, review round 1). Anything else refuses the turn before it starts, and
30	 * the configuration is built from prototype-free tables.
31	 */
32	
33	type Config = NonNullable<CodexOptions['config']>;
34	type ConfigValue = Config[string];
35	
36	const isTable = (value: unknown): value is Config =>
37	  typeof value === 'object' && value !== null && !Array.isArray(value);
38	
39	/** A node override the loop refuses to pass: the pinned definition cannot run as authored. */
40	export function overrideRefusal(path: string): Error {
41	  return Object.assign(
42	    new Error(
43	      `The Codex config override key ${JSON.stringify(path.slice(0, 200))} cannot be passed through --config, so the turn did not start: every key segment must be letters, digits, "_" or "-", and not __proto__, constructor or prototype.`,
44	    ),
45	    {
46	      code: 'HARNESS_INVALID_CONFIGURATION',
47	      retriable: false,
48	      submission: 'definitely-not-submitted' as const,
49	    },
50	  );
51	}
52	
53	/**
54	 * Features that bring the machine's own installs, account connectors or personal state into a
55	 * turn, or change what an unattended turn can do: ChatGPT apps, memories, lifecycle
56	 * hooks, sub-agent spawning (`multi_agent`) and goals. The CLI's own code-mode host
57	 * (`code_mode_host`) is its tool host, not an extension, and stays on: without it a turn runs no
58	 * command.
59	 */
60	export const ISOLATED_FEATURES = ['apps', 'memories', 'hooks', 'multi_agent', 'goals'] as const;
61	
62	/**
63	 * A configuration table whose keys are all its own (QA423-01). Server names and authored keys
64	 * such as `__proto__`, `constructor` or `toString` are ordinary keys to the CLI. A table without
65	 * a prototype stores and reads them as ordinary keys; on a plain object, assigning `__proto__`
66	 * changes the prototype instead and the key is lost, and the other names read inherited members.
67	 */
68	export function table(entries: Iterable<readonly [string, ConfigValue]> = []): Config {
69	  const out = Object.create(null) as Config;
70	  for (const [key, value] of entries) out[key] = value;
71	  return out;
72	}
73	
74	/** The defaults every loop turn starts from, before the node's overrides. */
75	export function isolationDefaults(): Config {
76	  return table([
77	    ['features', table(ISOLATED_FEATURES.map((name) => [name, false] as const))],
78	    ['notify', []],
79	  ]);
80	}
81	
82	/** `mcp_servers.<name>.enabled=false` for each server the machine configures, in listed order. */
83	export function serverSwitches(names: readonly string[]): Config {
84	  return names.length
85	    ? table([
86	        ['mcp_servers', table(names.map((name) => [name, table([['enabled', false]])] as const))],
87	      ])
88	    : table();
89	}
90	
91	/** Dotted keys become nested tables, as the CLI splits every `--config` key on dots. */
92	function expand(config: Config): Config {
93	  const out = table();
94	  for (const [key, raw] of Object.entries(config)) {
95	    const value = isTable(raw) ? expand(raw) : raw;
96	    const path = key.split('.');
97	    const leaf = path.pop()!;
98	    let current = out;
99	    for (const part of path) {
100	      const next = current[part];
101	      current = current[part] = isTable(next) ? next : table();
102	    }
103	    const existing = current[leaf];
104	    current[leaf] = isTable(value) && isTable(existing) ? merge(existing, value) : value;
105	  }
106	  return out;
107	}
108	
109	function merge(base: Config, override: Config): Config {
110	  const out = table(Object.entries(base));
111	  for (const [key, value] of Object.entries(override)) {
112	    const current = out[key];
113	    out[key] = isTable(current) && isTable(value) ? merge(current, value) : value;
114	  }
115	  return out;
116	}
117	
118	/**
119	 * Layer configurations; a later layer wins key path by key path. Arrays and scalars replace,
120	 * tables merge, as the CLI layers its own configuration.
121	 */
122	export function layerConfig(...layers: Config[]): Config {
123	  return layers.reduce<Config>((acc, layer) => merge(acc, expand(layer)), table());
124	}
125	
126	/** The CLI's own words for a failure: its non-empty lines joined, bounded to 300 characters. */
127	function excerpt(text: string): string {
128	  const lines = text
129	    .split(/\r?\n/)
130	    .map((line) => line.trim())
131	    .filter(Boolean);
132	  // A long startup warning (for example PATH aliases under a temporary CODEX_HOME) must not
133	  // consume the bound and hide the configuration error the owner needs to repair.
134	  const error = lines.findIndex((line) => /^error:/i.test(line));
135	  return (error < 0 ? lines : lines.slice(error)).join(' | ').slice(0, 300);
136	}
137	
138	function listingFailure(
139	  code: 'HARNESS_NOT_INSTALLED' | 'HARNESS_TURN_FAILED',
140	  reason: string,
141	): Error {
142	  return Object.assign(
143	    new Error(
144	      `Codex could not list the machine's MCP servers, so the turn did not start: ${reason}`,
145	    ),
146	    { code, retriable: false, submission: 'definitely-not-submitted' as const },
147	  );
148	}
149	
150	/**
151	 * Discovery must exclude plugin servers even though execution inherits plugins. Otherwise those
152	 * servers would be listed and disabled by serverSwitches, suppressing an enabled plugin's tools.
153	 * Never derive this list only from the execution defaults (ADR-0067).
154	 */
155	export const LISTING_ARGS = [
156	  'mcp',
157	  'list',
158	  '--json',
159	  ...['plugins', ...ISOLATED_FEATURES].flatMap((name) => ['--config', `features.${name}=false`]),
160	];
161	
162	/**
163	 * The names of the MCP servers the CLI would start in `cwd`, read from the CLI itself so every
164	 * configuration layer it loads (user, profile, trusted project) is included.
165	 */
166	export async function configuredServers(
167	  cli: CliCommand | undefined,
168	  run: CliRunner,
169	  timeoutMs: number,
170	  cwd: string | undefined,
171	  signal: AbortSignal | undefined,
172	): Promise<string[]> {
173	  if (!cli) throw listingFailure('HARNESS_NOT_INSTALLED', 'the Codex CLI was not found.');
174	  const result = await run({ ...cli, ...(cwd ? { cwd } : {}) }, LISTING_ARGS, timeoutMs, signal);
175	  if (result.spawnError !== undefined)
176	    throw listingFailure(
177	      /enoent/i.test(result.spawnError) ? 'HARNESS_NOT_INSTALLED' : 'HARNESS_TURN_FAILED',
178	      `the CLI did not run (${result.spawnError}).`,
179	    );
180	  if (result.code !== 0)
181	    throw listingFailure(
182	      'HARNESS_TURN_FAILED',
183	      `mcp list exited ${result.code}: ${excerpt(result.output)}`,
184	    );
185	  // Only stdout carries the JSON; warnings or logs the CLI writes to stderr are not part of it.
186	  let listed: unknown;
187	  try {
188	    listed = JSON.parse(result.stdout);
189	  } catch {
190	    throw listingFailure(
191	      'HARNESS_TURN_FAILED',
192	      `mcp list printed no JSON: ${excerpt(result.stdout)}`,
193	    );
194	  }
195	  if (
196	    !Array.isArray(listed) ||
197	    !listed.every((entry) => isTable(entry) && typeof entry['name'] === 'string')
198	  )
199	    throw listingFailure('HARNESS_TURN_FAILED', 'mcp list printed an unexpected shape.');
200	  const names = listed.map((entry) => (entry as { name: string }).name);
201	  // Validated before any argument is built: a name the loop cannot pass as one plain key stops
202	  // the turn rather than leaving that server enabled (QA423-01).
203	  const unusable = names.find((name) => !plainCodexConfigSegment(name));
204	  if (unusable !== undefined)
205	    throw listingFailure(
206	      'HARNESS_TURN_FAILED',
207	      `the server name ${JSON.stringify(unusable.slice(0, 100))} cannot be switched off through --config.`,
208	    );
209	  return names;
210	}
