363	    code: transient ? 'HARNESS_TRANSPORT_FAILED' : 'HARNESS_TURN_FAILED',
364	    message,
365	    retriable: transient,
366	  };
367	}
368	
369	export interface TurnOutcome {
370	  finalText: string;
371	  usage: Usage;
372	  items: HarnessItem[];
373	  /** Set when the turn failed (`turn.failed`, or a fatal stream error with no completion). */
374	  failure?: ClassifiedError;
375	  completed: boolean;
376	}
377	
378	/**
379	 * Stateful translation of one turn's event stream. `push` returns the `HarnessEvent`s to emit for
380	 * each Codex event; `finish` closes the turn and reports the outcome.
381	 *
382	 * - `thread.started` becomes a `session` event, immediately, so the engine can persist the id.
383	 * - Items are emitted on `item.completed` only; `item.started` and `item.updated` are progress
384	 *   noise for a node-level view and would duplicate entries.
385	 * - An `error` item (for example a configuration deprecation warning) is a normal item, not a
386	 *   failure. `turn.failed` is the failure signal. Top-level errors, `turn.failed` and thrown failures share the evidence precedence;
387	 *   successful turns tolerate nonfatal top-level diagnostics.
388	 * - The SDK's process-exit error (`Codex Exec exited with code 1: <stderr>`) only wraps a failure
389	 *   the stream already reported, and the CLI's stderr is usually just its startup banner. Once the
390	 *   stream has reported an error or `turn.failed` for an unfinished turn, that exact wrapper never
391	 *   replaces the stream's evidence while it classifies as generic (lowest rank). Every other
392	 *   thrown error, such as a protocol parse failure, joins the fold as usual. The wrapper's stderr
393	 *   is compared piece by piece (each line, read from the provider error it holds when it holds
394	 *   one): a piece that exactly repeats evidence the stream reported (code, message, retry and
395	 *   submission) adds nothing, while every other typed piece joins the fold in order, so a
396	 *   distinct cause beside a repeat still counts (PR #426 audit scans 2 and 3). This holds while
397	 *   the stream's evidence is fatal, even after `turn.completed`.
398	 */
399	export class TurnAccumulator {
400	  private submitted = false;
401	  private finalText = '';
402	  private usage: Usage = ZERO_USAGE;
403	  private readonly items: HarnessItem[] = [];
404	  private failure: ClassifiedError | undefined;
405	  private fatal = false;
406	  private completed = false;
407	  /** What the stream itself reported as failing: each classification and structured text. */
408	  private readonly streamReports: ClassifiedError[] = [];
409	  /** The stream reported `turn.failed` or a terminal/pinned error, so the turn failed. */
410	  private streamFatal = false;
411	  sessionId: string | undefined;
412	
413	  constructor(private readonly mode: 'fresh' | 'resumed') {}
414	
415	  push(event: ThreadEvent | { type: string }): HarnessEvent[] {
416	    const ev = event as ThreadEvent;
417	    switch (ev.type) {
418	      case 'thread.started':
419	        this.sessionId = ev.thread_id;
420	        return [{ type: 'session', sessionId: ev.thread_id, mode: this.mode }];
421	      case 'turn.started':
422	        if (this.submitted) return [];
423	        this.submitted = true;
424	        return [{ type: 'submitted', marker: 'codex.turn.started' }];
425	      case 'item.completed': {
426	        const item = normalizeItem(ev.item);
427	        this.items.push(item);
428	        if (ev.item.type === 'agent_message') this.finalText = ev.item.text;
429	        return [{ type: 'item', item }];
430	      }
431	      case 'turn.completed':
432	        this.completed = true;
433	        this.usage = mapUsage(ev.usage);
434	        return [{ type: 'usage', usage: this.usage }, { type: 'turn-complete' }];
435	      case 'turn.failed':
436	        this.add(this.report(ev.error, true), false);
437	        return [];
438	      case 'error':
439	        // Native top-level errors and turn.failed use the same evidence fold. A completed
440	        // turn may tolerate diagnostics, but terminal/pinned refusals are not diagnostics.
441	        this.add(this.report(ev, false), true);
442	        return [];
443	      default:
444	        return [];
445	    }
446	  }
447	
448	  /** Classify a failure the stream reported and remember it, to recognise a later repeat. */
449	  private report(error: unknown, failed: boolean): ClassifiedError {
450	    const classified = classifyCodexError(error);
451	    this.streamReports.push(classified);
452	    this.streamFatal ||= failed || harnessFailureRank(classified) >= 4;
453	    return classified;
454	  }
455	
456	  /** Exactly the evidence the stream already reported: code, message, retry and submission. */
457	  private repeatsStream(piece: ClassifiedError): boolean {
458	    return this.streamReports.some(
459	      (reported) =>
460	        reported.code === piece.code &&
461	        reported.message === piece.message &&
462	        reported.retriable === piece.retriable &&
463	        reported.submission === piece.submission,
464	    );
465	  }
466	
467	  /**
468	   * Whether the stream itself reported this turn's failure: fatal evidence such as `turn.failed`
469	   * or a pinned refusal, whatever the completion flag says, or any reported error of an unfinished
470	   * turn.
471	   */
472	  private streamFailed(): boolean {
473	    return this.streamFatal || (!this.completed && this.streamReports.length > 0);
474	  }
475	
476	  /** Record a failure raised outside the event stream (a thrown SDK or process error). */
477	  fail(error: unknown): void {
478	    if (!isProcessExitWrapper(error)) {
479	      // Any other thrown error, such as a protocol parse failure, is evidence of its own.
480	      this.add(classifyCodexError(error), false);
481	      return;
482	    }
483	    // The SDK's exit error carries the CLI's stderr. Each typed cause there that the stream did
484	    // not already report joins the fold in order, so ranking and the later-observation rule
485	    // apply to it; an exact repeat of the stream's evidence adds nothing (#243).
486	    const fresh = stderrEvidence(error).filter(
487	      (piece) => harnessFailureRank(piece) > 1 && !this.repeatsStream(piece),
488	    );
489	    for (const piece of fresh) this.add(piece, false);
490	    if (fresh.length) return;
491	    if (this.streamFailed()) {
492	      // A generic wrapper of the failure the stream reported: the process failed, nothing more.
493	      this.fatal = true;
494	      return;
495	    }
496	    this.add(classifyCodexError(error), false);
497	  }
498	
499	  private add(next: ClassifiedError, diagnostic: boolean): void {
500	    this.failure = mergeHarnessFailure(this.failure, next);
501	    this.fatal ||= !diagnostic || harnessFailureRank(next) >= 4;
502	  }
503	
504	  finish(): TurnOutcome {
505	    const failure =
506	      this.completed && !this.fatal
507	        ? undefined
508	        : (this.failure ??
509	          (!this.completed
510	            ? classifyCodexError('the Codex event stream ended before the turn completed')
511	            : undefined));
512	    return {
513	      finalText: this.finalText,
514	      usage: this.usage,
515	      items: [...this.items],
