    ...request.routes.map((route) => `- ${route.id}: ${route.label}`),
    '',
    'Context (JSON):',
    contextBlock(request.context),
    '',
    'Do not run commands or change files. Return the route id, confidence between 0 and 1, and short reasoning.',
  ].join('\n');
}
